package com.railway.model;
import java.math.BigDecimal;import java.sql.Time;
public class Train {private long id;private String number,name,source,destination;private Time departure,arrival;private BigDecimal fare;private int availableSeats;public long getId(){return id;}public void setId(long v){id=v;}public String getNumber(){return number;}public void setNumber(String v){number=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getSource(){return source;}public void setSource(String v){source=v;}public String getDestination(){return destination;}public void setDestination(String v){destination=v;}public Time getDeparture(){return departure;}public void setDeparture(Time v){departure=v;}public Time getArrival(){return arrival;}public void setArrival(Time v){arrival=v;}public BigDecimal getFare(){return fare;}public void setFare(BigDecimal v){fare=v;}public int getAvailableSeats(){return availableSeats;}public void setAvailableSeats(int v){availableSeats=v;}}
